'use strict';

/**
* LAPACK routine to generate one of the real orthogonal matrices `Q` or `P^T` determined by `DGEBRD` when reducing a real matrix `A` to bidiagonal form: `A = Q * B * P^T`.
*
* @module @stdlib/lapack/base/dorgbr
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dorgbr = require( '@stdlib/lapack/base/dorgbr' );
*
* var A = new Float64Array( [ 1, 0.2, -0.1, 0.3, 0, 1, 0.4, -0.2, 0, 0, 1, 0.5 ] );
* var TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
* var WORK = new Float64Array( 10 );
*
* var info = dorgbr( 'column-major', 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 );
* // A => <Float64Array>[ -0.3, -0.26, 0.13, -0.39, -0.143, 0.0714, -0.3457, 0.1371, ~0.21, ~-0.021, ~-0.146, ~-0.474 ]
* // info => 0
* // WORK[ 0 ] => 96
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dorgbr;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dorgbr = main;
} else {
	dorgbr = tmp;
}


// EXPORTS //

module.exports = dorgbr;

// exports: { "ndarray": "dorgbr.ndarray" }
